observation.query:
SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_31f7149343d3329d>
    <urn:graphragprov:unit:u_54a5719fdf133879>
    <urn:graphragprov:unit:u_759899f2608ed171>
    <urn:graphragprov:unit:u_ff03f873383d6331>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
